from dataclasses import dataclass, field

@dataclass
class Order:
    id: int
    amount: float
    status: str = 'pending'
    tags: list = field(default_factory=list)  # safe mutable default

o = Order(id=1, amount=1500.0)
print(o)           # Order(id=1, amount=1500.0, status='pending', tags=[])
print(o.amount)    # 1500.0

